static void CHTerminateApplicationIfRunning(NSString *bundleID) {
    Class serviceClass = NSClassFromString(@"FBSSystemService");
    SEL sharedSelector = NSSelectorFromString(@"sharedService");
    id service = [serviceClass respondsToSelector:sharedSelector] ? [serviceClass performSelector:sharedSelector] : nil;
    SEL terminateSelector = NSSelectorFromString(@"terminateApplication:forReason:andReport:withDescription:");
    NSMethodSignature *signature = [service methodSignatureForSelector:terminateSelector];
    if (!service || !signature || ![service respondsToSelector:terminateSelector]) return;
    NSInvocation *invocation = [NSInvocation invocationWithMethodSignature:signature];
    NSInteger reason = 1;
    BOOL report = NO;
    NSString *description = @"Chameleon container switch";
    invocation.target = service;
    invocation.selector = terminateSelector;
    [invocation setArgument:&bundleID atIndex:2];
    [invocation setArgument:&reason atIndex:3];
    [invocation setArgument:&report atIndex:4];
    [invocation setArgument:&description atIndex:5];
    [invocation invoke];
}

static void CHPromptText(UIViewController *controller, NSString *title, NSString *message, NSString *value, void (^completion)(NSString *)) {
    UIAlertController *a = [UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];
    [a addTextFieldWithConfigurationHandler:^(UITextField *f) { f.text = value ?: @""; f.clearButtonMode = UITextFieldViewModeWhileEditing; }];
    [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];
    [a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x) { NSString *v = [a.textFields.firstObject.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; completion(v); }]];
    [controller presentViewController:a animated:YES completion:nil];
}

