        @[@{@"title": @"Pixel Width", @"key": @"screenWidth", @"example": @"1290"}, @{@"title": @"Pixel Height", @"key": @"screenHeight", @"example": @"2796"}, @{@"title": @"Scale", @"key": @"screenScale", @"example": @"3"}, @{@"title": @"PPI", @"key": @"ppi", @"example": @"460"}],
