@implementation CHAppLibraryController
- (instancetype)initWithStore:(CHProfileStore *)store { if ((self = [super initWithStyle:UITableViewStyleInsetGrouped])) _store = store; return self; }
- (void)viewDidLoad { [super viewDidLoad]; self.title = @"Applications"; self.navigationItem.largeTitleDisplayMode = UINavigationItemLargeTitleDisplayModeAlways; self.overrideUserInterfaceStyle = UIUserInterfaceStyleDark; self.tableView.backgroundColor = UIColor.blackColor; self.tableView.separatorColor = [UIColor colorWithWhite:1 alpha:.1]; self.searchController = [[UISearchController alloc] initWithSearchResultsController:nil]; self.searchController.searchResultsUpdater = self; self.searchController.obscuresBackgroundDuringPresentation = NO; self.searchController.searchBar.placeholder = @"Search installed apps"; self.navigationItem.searchController = self.searchController; self.navigationItem.rightBarButtonItem = [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemRefresh target:self action:@selector(reloadApplications)]; [self reloadApplications]; }
- (void)reloadApplications { self.applications = [CHInstalledAppCatalog thirdPartyApplications]; [self updateSearchResultsForSearchController:self.searchController]; }
- (void)updateSearchResultsForSearchController:(UISearchController *)sc { NSString *q = sc.searchBar.text.lowercaseString; self.visibleApplications = q.length ? [self.applications filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *app, NSDictionary *b) { return [[app[@"name"] lowercaseString] containsString:q] || [[app[@"bundleID"] lowercaseString] containsString:q]; }]] : self.applications; NSMutableDictionary *groups = [NSMutableDictionary dictionary]; for (NSDictionary *app in self.visibleApplications) { NSString *name = app[@"name"] ?: @"#"; NSString *key = name.length ? [[name substringToIndex:1] uppercaseString] : @"#"; if (![[NSCharacterSet letterCharacterSet] characterIsMember:[key characterAtIndex:0]]) key = @"#"; groups[key] = groups[key] ? [groups[key] arrayByAddingObject:app] : @[app]; } self.sectionTitles = [[groups.allKeys sortedArrayUsingSelector:@selector(compare:)] copy]; NSMutableArray *sections = [NSMutableArray array]; for (NSString *key in self.sectionTitles) [sections addObject:[groups[key] sortedArrayUsingDescriptors:@[[NSSortDescriptor sortDescriptorWithKey:@"name" ascending:YES]]]]; self.sectionedApplications = sections; [self.tableView reloadData]; }
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t { return MAX((NSUInteger)1, self.sectionTitles.count); }
