- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s { return s == self.sectionedApplications.count - 1 ? @"Only installed third-party applications are shown." : nil; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { UITableViewCell *c = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil]; c.backgroundColor = [UIColor colorWithWhite:.11 alpha:1]; c.textLabel.textColor = UIColor.whiteColor; c.detailTextLabel.textColor = UIColor.secondaryLabelColor; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; if (!self.sectionedApplications.count) { c.textLabel.text = @"No third-party apps detected"; return c; } NSDictionary *app = self.sectionedApplications[p.section][p.row]; NSUInteger n = 0; for (NSDictionary *e in self.store.profiles) if ([e[@"apps"] containsObject:app[@"bundleID"]]) n++; c.textLabel.text = app[@"name"]; c.detailTextLabel.text = n ? [NSString stringWithFormat:@"%lu container%@", (unsigned long)n, n == 1 ? @"" : @"s"] : app[@"bundleID"]; c.imageView.image = app[@"icon"] ?: [UIImage systemImageNamed:@"app.fill"]; c.imageView.layer.cornerRadius = 10; c.imageView.layer.masksToBounds = YES; return c; }
