@implementation CHAppContainersController
- (void)viewDidLoad { [super viewDidLoad]; self.title = @"Containers"; self.overrideUserInterfaceStyle = UIUserInterfaceStyleDark; self.tableView.backgroundColor = UIColor.blackColor; self.navigationItem.rightBarButtonItem = [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(createContainer)]; UILongPressGestureRecognizer *g = [[UILongPressGestureRecognizer alloc] initWithTarget:self action:@selector(longPressed:)]; g.minimumPressDuration = .45; [self.tableView addGestureRecognizer:g]; }
- (void)viewWillAppear:(BOOL)animated { [super viewWillAppear:animated]; [self reloadContainers]; }
- (void)reloadContainers { NSMutableArray *a = [NSMutableArray array]; for (NSDictionary *e in self.store.profiles) if ([e[@"apps"] containsObject:self.application[@"bundleID"]]) [a addObject:e]; self.containers = a; [self.tableView reloadData]; }
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t { return 2; }
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s { return s == 0 ? 1 : MAX((NSUInteger)1, self.containers.count); }
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s { return s == 0 ? @"Application" : @"App containers"; }
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s { return s == 1 ? @"Tap a container to open it. Long-press for settings and generated identifiers." : nil; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { UITableViewCell *c = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil]; c.backgroundColor = [UIColor colorWithWhite:.11 alpha:1]; c.textLabel.textColor = UIColor.whiteColor; c.detailTextLabel.textColor = UIColor.secondaryLabelColor; if (p.section == 0) { c.textLabel.text = self.application[@"name"]; c.detailTextLabel.text = self.application[@"bundleID"]; c.imageView.image = self.application[@"icon"] ?: [UIImage systemImageNamed:@"app.fill"]; return c; } if (!self.containers.count) { c.textLabel.text = @"Create the first container"; c.detailTextLabel.text = @"Tap + to create an app-specific session"; c.imageView.image = [UIImage systemImageNamed:@"plus.circle.fill"]; c.imageView.tintColor = UIColor.systemGreenColor; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; return c; } NSDictionary *e = self.containers[p.row]; BOOL active = [e[@"id"] isEqual:self.store.activeProfileID]; c.textLabel.text = e[@"name"] ?: @"Container"; c.detailTextLabel.text = [NSString stringWithFormat:@"%@  •  %@", active ? @"Running" : @"Ready", [e[@"id"] substringToIndex:MIN((NSUInteger)8, [e[@"id"] length])]]; c.imageView.image = [UIImage systemImageNamed:active ? @"checkmark.circle.fill" : @"shippingbox.fill"]; c.imageView.tintColor = active ? UIColor.systemGreenColor : UIColor.secondaryLabelColor; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { [t deselectRowAtIndexPath:p animated:YES]; if (p.section != 1) return; if (!self.containers.count) { [self createContainer]; return; } [self openContainer:self.containers[p.row]]; }
- (void)longPressed:(UILongPressGestureRecognizer *)g { if (g.state != UIGestureRecognizerStateBegan) return; NSIndexPath *p = [self.tableView indexPathForRowAtPoint:[g locationInView:self.tableView]]; if (p && p.section == 1 && p.row < self.containers.count) [self openContainer:self.containers[p.row]]; }
- (void)openContainer:(NSDictionary *)e { [self.navigationController pushViewController:[[CHProfileDetailController alloc] initWithStore:self.store application:self.application profileID:e[@"id"]] animated:YES]; }
- (void)createContainer { NSString *s = [NSString stringWithFormat:@"Container %lu", (unsigned long)self.containers.count + 1]; CHPromptText(self, @"New container", @"Create an app-owned data session.", s, ^(NSString *name) { [self.store addProfileNamed:name]; NSUInteger i = self.store.profiles.count - 1; [self.store addBundleID:self.application[@"bundleID"] toProfileAtIndex:i]; [self.store activateProfileAtIndex:i]; [self reloadContainers]; [self openContainer:self.store.profiles[i]]; }); }
@end

@implementation CHProfileDetailController
- (instancetype)initWithStore:(CHProfileStore *)store application:(NSDictionary *)application profileID:(NSString *)profileID { if ((self = [super initWithStyle:UITableViewStyleInsetGrouped])) { _store = store; _application = application; _profileID = [profileID copy]; } return self; }
