- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s { return @[@"Identity", @"Runtime", @"Generated values", @"Container options", @"Launch"][s]; }
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s { if (s == 0) return [NSString stringWithFormat:@"Values belong to this app container.\nEffective root: %@", self.effectiveDataRoot]; if (s == 1) return @"The selected profile is activated and the target is cleanly relaunched before runtime hooks load."; if (s == 2) return @"Generate creates fresh local session aliases."; return nil; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { NSDictionary *e = self.profile; UITableViewCell *c = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleValue1 reuseIdentifier:nil]; c.backgroundColor = [UIColor colorWithWhite:.11 alpha:1]; c.textLabel.textColor = UIColor.whiteColor; c.detailTextLabel.textColor = UIColor.secondaryLabelColor; if (p.section == 0) { NSArray *l = @[@"Application", @"Bundle ID", @"Container ID", @"Container name"]; c.textLabel.text = l[p.row]; c.detailTextLabel.text = p.row == 0 ? self.application[@"name"] : (p.row == 1 ? self.application[@"bundleID"] : (p.row == 2 ? e[@"id"] : e[@"name"])); c.accessoryType = p.row == 3 ? UITableViewCellAccessoryDisclosureIndicator : UITableViewCellAccessoryNone; } else if (p.section == 1) { NSDictionary *proxy = e[@"proxy"], *loc = e[@"location"], *device = e[@"device"]; NSArray *labels = @[@"Proxy configuration", @"Proxy enabled", @"Location picker", @"Location enabled", @"Device identity"]; c.textLabel.text = labels[p.row]; if (p.row == 0) { c.detailTextLabel.text = [proxy[@"host"] length] ? [NSString stringWithFormat:@"%@:%@", proxy[@"host"], proxy[@"port"] ?: @0] : @"Not configured"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } else if (p.row == 1 || p.row == 3) { BOOL proxyRow = p.row == 1; UISwitch *sw = [UISwitch new]; sw.tag = proxyRow ? 301 : 302; sw.on = [proxyRow ? proxy[@"enabled"] : loc[@"enabled"] boolValue]; [sw addTarget:self action:@selector(runtimeOptionChanged:) forControlEvents:UIControlEventValueChanged]; c.accessoryView = sw; c.detailTextLabel.text = sw.on ? @"On" : @"Off"; } else if (p.row == 2) { c.detailTextLabel.text = [loc[@"label"] length] ? loc[@"label"] : @"Not configured"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } else { c.detailTextLabel.text = [device[@"enabled"] boolValue] ? (device[@"marketingName"] ?: @"Enabled") : @"Off"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } } else if (p.section == 2) { NSArray *l = @[@"Vendor alias", @"Advertising alias", @"Session label", @"Generate fresh values"]; NSArray *k = @[@"vendorAlias", @"advertisingAlias", @"sessionLabel", @""]; c.textLabel.text = l[p.row]; c.detailTextLabel.text = p.row < 3 ? (e[@"metadata"][k[p.row]] ?: @"Not set") : @"UUID aliases"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } else if (p.section == 3) { c.textLabel.text = @"Container protection"; c.detailTextLabel.text = [e[@"containerOptions"][@"containerProtection"] boolValue] ? @"On" : @"Off"; UISwitch *sw = [UISwitch new]; sw.on = [e[@"containerOptions"][@"containerProtection"] boolValue]; sw.tag = 201; [sw addTarget:self action:@selector(optionChanged:) forControlEvents:UIControlEventValueChanged]; c.accessoryView = sw; } else { c.textLabel.text = @"Launch application"; c.imageView.image = self.application[@"icon"] ?: [UIImage systemImageNamed:@"arrow.up.forward.app.fill"]; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { [t deselectRowAtIndexPath:p animated:YES]; if (p.section == 0 && p.row == 3) { CHPromptText(self, @"Container name", nil, self.profile[@"name"], ^(NSString *v) { [self.store renameProfileAtIndex:self.profileIndex name:v]; [self.tableView reloadData]; }); } else if (p.section == 1) { if (p.row == 0) [self configureProxy]; else if (p.row == 2) [self configureLocation]; else if (p.row == 4) [self.navigationController pushViewController:[[CHDeviceProfileController alloc] initWithStore:self.store profileID:self.profileID] animated:YES]; } else if (p.section == 2) { if (p.row < 3) { NSArray *k = @[@"vendorAlias", @"advertisingAlias", @"sessionLabel"]; CHPromptText(self, @[@"Vendor alias", @"Advertising alias", @"Session label"][p.row], nil, self.profile[@"metadata"][k[p.row]], ^(NSString *v) { [self.store setMetadataValue:v forKey:k[p.row] profileAtIndex:self.profileIndex]; [self.tableView reloadData]; }); } else [self generateValues]; } else if (p.section == 4) [self launchApp]; }
- (void)generateValues { for (NSString *k in @[@"vendorAlias", @"advertisingAlias", @"sessionLabel"]) [self.store setMetadataValue:NSUUID.UUID.UUIDString.lowercaseString forKey:k profileAtIndex:self.profileIndex]; [self.tableView reloadData]; }
- (void)optionChanged:(UISwitch *)sw { [self.store setContainerOption:sw.on key:@"containerProtection" forProfileAtIndex:self.profileIndex]; }
- (void)runtimeOptionChanged:(UISwitch *)sw { if (sw.tag == 301) [self.store setProxyEnabled:sw.on forProfileAtIndex:self.profileIndex]; else if (sw.tag == 302) [self.store setLocationEnabled:sw.on forProfileAtIndex:self.profileIndex]; [self.tableView reloadData]; }
- (void)configureProxy { NSDictionary *p = self.profile[@"proxy"]; UIAlertController *a = [UIAlertController alertControllerWithTitle:@"Proxy" message:@"Types: http, https, or socks5. Standard URL-session traffic uses this proxy after relaunch." preferredStyle:UIAlertControllerStyleAlert]; for (NSString *s in @[@"Type", @"Host", @"Port", @"Username (optional)", @"Password (optional)"]) [a addTextFieldWithConfigurationHandler:^(UITextField *f) { f.placeholder = s; f.secureTextEntry = [s hasPrefix:@"Password"]; if ([s isEqualToString:@"Port"]) f.keyboardType = UIKeyboardTypeNumberPad; }]; NSArray *v = @[p[@"type"] ?: @"http", p[@"host"] ?: @"", p[@"port"] ? [p[@"port"] stringValue] : @"", p[@"username"] ?: @"", p[@"password"] ?: @""]; [a.textFields enumerateObjectsUsingBlock:^(UITextField *f, NSUInteger i, BOOL *stop) { f.text = v[i]; }]; [a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; [a addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x) { [self.store setProxyType:a.textFields[0].text host:a.textFields[1].text port:[a.textFields[2].text integerValue] username:a.textFields[3].text password:a.textFields[4].text forProfileAtIndex:self.profileIndex]; [self.tableView reloadData]; }]]; [self presentViewController:a animated:YES completion:nil]; }
- (void)configureLocation { CHMapController *m = [CHMapController new]; m.store = self.store; m.profileIndex = self.profileIndex; [self presentViewController:[[UINavigationController alloc] initWithRootViewController:m] animated:YES completion:nil]; }
- (void)launchApp { NSUInteger index = self.profileIndex; if (index == NSNotFound) return; NSString *bundleID = self.application[@"bundleID"]; [self.store activateProfileAtIndex:index]; CHTerminateApplicationIfRunning(bundleID); dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(700 * NSEC_PER_MSEC)), dispatch_get_main_queue(), ^{ Class c = NSClassFromString(@"LSApplicationWorkspace"); id w = [c performSelector:@selector(defaultWorkspace)]; if ([w respondsToSelector:@selector(openApplicationWithBundleID:)]) [w performSelector:@selector(openApplicationWithBundleID:) withObject:bundleID]; }); }
@end

