- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s { if (s == 0) return @"Overrides load when the selected application starts."; if (s == 3) return @"Serial, IMEI, MEID, and Wi-Fi MAC are retained as local test fixtures; they do not rewrite physical hardware or the modem."; return nil; }
- (NSArray<NSString *> *)validationIssues { NSDictionary *d = self.device ?: @{}; NSMutableArray *a = [NSMutableArray array]; NSString *seed = [d[@"idfvSeed"] description]; if (seed.length && ![[NSUUID alloc] initWithUUIDString:seed]) [a addObject:@"IDFV Seed must be a UUID."]; if ([d[@"physicalMemoryGB"] doubleValue] < 0) [a addObject:@"Physical memory cannot be negative."]; double w = [d[@"screenWidth"] doubleValue], h = [d[@"screenHeight"] doubleValue], scale = [d[@"screenScale"] doubleValue]; if ((w > 0 || h > 0) && (w <= 0 || h <= 0 || scale <= 0)) [a addObject:@"Display width, height, and scale must be set together."]; NSCharacterSet *digits = NSCharacterSet.decimalDigitCharacterSet; NSString *mcc = [d[@"mcc"] description], *mnc = [d[@"mnc"] description], *imei = [d[@"imeiFixture"] description]; if (mcc.length && (mcc.length != 3 || [mcc rangeOfCharacterFromSet:digits.invertedSet].location != NSNotFound)) [a addObject:@"MCC must contain exactly three digits."]; if (mnc.length && ((mnc.length < 2 || mnc.length > 3) || [mnc rangeOfCharacterFromSet:digits.invertedSet].location != NSNotFound)) [a addObject:@"MNC must contain two or three digits."]; if (imei.length && (imei.length != 15 || [imei rangeOfCharacterFromSet:digits.invertedSet].location != NSNotFound)) [a addObject:@"IMEI fixture must contain 15 digits."]; NSString *meid = [d[@"meidFixture"] description]; NSCharacterSet *hex = [NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdefABCDEF"]; if (meid.length && (meid.length != 14 || [meid rangeOfCharacterFromSet:hex.invertedSet].location != NSNotFound)) [a addObject:@"MEID fixture must contain 14 hexadecimal characters."]; NSString *zone = [d[@"timeZone"] description]; if (zone.length && ![NSTimeZone timeZoneWithName:zone]) [a addObject:@"Timezone is not recognized by iOS."]; NSString *machine = [d[@"machine"] description]; NSDictionary *preset = nil; for (NSDictionary *candidate in CHDevicePresets()) if ([candidate[@"machine"] isEqual:machine]) { preset = candidate; break; } if (preset) { for (NSString *key in @[@"marketingName", @"hardwareModel"]) if ([[d[key] description] length] && ![[d[key] description] isEqual:[preset[key] description]]) [a addObject:[NSString stringWithFormat:@"%@ does not match %@.", key, machine]]; for (NSString *key in @[@"physicalMemoryGB", @"screenWidth", @"screenHeight", @"screenScale", @"ppi"]) if ([d[key] doubleValue] > 0 && fabs([d[key] doubleValue] - [preset[key] doubleValue]) > .01) [a addObject:[NSString stringWithFormat:@"%@ does not match %@.", key, machine]]; NSInteger major = [[[d[@"systemVersion"] description] componentsSeparatedByString:@"."] firstObject].integerValue; if (major > 0 && major < [preset[@"minimumSystemMajor"] integerValue]) [a addObject:@"System version predates the selected device model."]; } return a; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { UITableViewCell *c = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleValue1 reuseIdentifier:nil]; c.backgroundColor = [UIColor colorWithWhite:.11 alpha:1]; c.textLabel.textColor = UIColor.whiteColor; c.detailTextLabel.textColor = UIColor.secondaryLabelColor; if (p.section == 0) { if (p.row == 0) { c.textLabel.text = @"Enabled"; UISwitch *sw = [UISwitch new]; sw.on = [self.device[@"enabled"] boolValue]; [sw addTarget:self action:@selector(identityToggled:) forControlEvents:UIControlEventValueChanged]; c.accessoryView = sw; } else if (p.row == 1) { c.textLabel.text = @"Apply device preset"; NSString *name = self.device[@"marketingName"]; c.detailTextLabel.text = name.length ? name : @"Custom"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } else { NSArray *issues = self.validationIssues; c.textLabel.text = @"Consistency check"; c.detailTextLabel.text = issues.count ? [NSString stringWithFormat:@"%lu issue%@", (unsigned long)issues.count, issues.count == 1 ? @"" : @"s"] : @"Valid"; c.detailTextLabel.textColor = issues.count ? UIColor.systemOrangeColor : UIColor.systemGreenColor; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; } return c; } NSDictionary *field = CHDeviceFieldSections()[p.section - 1][p.row]; NSString *display = [[self.device objectForKey:field[@"key"]] description]; c.textLabel.text = field[@"title"]; c.detailTextLabel.text = display.length ? display : @"Not set"; c.accessoryType = UITableViewCellAccessoryDisclosureIndicator; return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { [t deselectRowAtIndexPath:p animated:YES]; if (p.section == 0) { if (p.row == 1) { UIAlertController *sheet = [UIAlertController alertControllerWithTitle:@"Device preset" message:@"Apply a coherent hardware set. Regional and identifier fields are unchanged." preferredStyle:UIAlertControllerStyleActionSheet]; for (NSDictionary *preset in CHDevicePresets()) [sheet addAction:[UIAlertAction actionWithTitle:preset[@"marketingName"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *x) { NSMutableDictionary *values = [preset mutableCopy]; [values removeObjectForKey:@"minimumSystemMajor"]; [self.store setDeviceValues:values profileAtIndex:self.profileIndex]; [self.tableView reloadData]; }]]; [sheet addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]]; sheet.popoverPresentationController.sourceView = t; sheet.popoverPresentationController.sourceRect = [t rectForRowAtIndexPath:p]; [self presentViewController:sheet animated:YES completion:nil]; } else if (p.row == 2) { NSArray *issues = self.validationIssues; UIAlertController *alert = [UIAlertController alertControllerWithTitle:issues.count ? @"Profile issues" : @"Profile valid" message:issues.count ? [issues componentsJoinedByString:@"\n"] : @"The configured fields are internally well-formed." preferredStyle:UIAlertControllerStyleAlert]; [alert addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleDefault handler:nil]]; [self presentViewController:alert animated:YES completion:nil]; } return; } NSDictionary *field = CHDeviceFieldSections()[p.section - 1][p.row]; NSString *current = [[self.device objectForKey:field[@"key"]] description] ?: @""; CHPromptText(self, field[@"title"], [NSString stringWithFormat:@"Example: %@", field[@"example"]], current, ^(NSString *value) { [self.store setDeviceValue:value forKey:field[@"key"] profileAtIndex:self.profileIndex]; [self.tableView reloadData]; }); }
- (void)identityToggled:(UISwitch *)sw { [self.store setDeviceEnabled:sw.on profileAtIndex:self.profileIndex]; [self.tableView reloadData]; }
@end
